CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,avatar_emoji TEXT NOT NULL DEFAULT '✨',bio TEXT NOT NULL DEFAULT '',is_developer BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS follows(follower_id BIGINT REFERENCES users ON DELETE CASCADE,following_id BIGINT REFERENCES users ON DELETE CASCADE,created_at TIMESTAMPTZ DEFAULT NOW(),PRIMARY KEY(follower_id,following_id),CHECK(follower_id<>following_id));
CREATE TABLE IF NOT EXISTS posts(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users ON DELETE CASCADE,body TEXT NOT NULL DEFAULT '',media_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS lums(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users ON DELETE CASCADE,caption TEXT DEFAULT '',media_url TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS stories(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users ON DELETE CASCADE,media_url TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS wallet_transactions(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users ON DELETE CASCADE,amount BIGINT NOT NULL,reason TEXT NOT NULL,reference_type TEXT,reference_id TEXT,idempotency_key TEXT UNIQUE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_progress(user_id BIGINT PRIMARY KEY REFERENCES users ON DELETE CASCADE,xp BIGINT NOT NULL DEFAULT 0,level INTEGER NOT NULL DEFAULT 1,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS missions(id BIGSERIAL PRIMARY KEY,mission_key TEXT UNIQUE NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,target_count INTEGER NOT NULL,xp_reward INTEGER DEFAULT 0,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS user_missions(user_id BIGINT REFERENCES users ON DELETE CASCADE,mission_id BIGINT REFERENCES missions ON DELETE CASCADE,progress INTEGER DEFAULT 0,completed_at TIMESTAMPTZ,PRIMARY KEY(user_id,mission_id));
CREATE TABLE IF NOT EXISTS milestones(id BIGSERIAL PRIMARY KEY,milestone_key TEXT UNIQUE NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,threshold BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS user_milestones(user_id BIGINT REFERENCES users ON DELETE CASCADE,milestone_id BIGINT REFERENCES milestones ON DELETE CASCADE,unlocked_at TIMESTAMPTZ DEFAULT NOW(),PRIMARY KEY(user_id,milestone_id));
CREATE TABLE IF NOT EXISTS relationships(user_low BIGINT REFERENCES users ON DELETE CASCADE,user_high BIGINT REFERENCES users ON DELETE CASCADE,stage TEXT DEFAULT 'Acquaintances',relationship_xp BIGINT DEFAULT 0,last_meaningful_interaction_at TIMESTAMPTZ,family_role TEXT,updated_at TIMESTAMPTZ DEFAULT NOW(),PRIMARY KEY(user_low,user_high),CHECK(user_low<user_high),CHECK(stage IN ('Acquaintances','Friends','Close Friends','Best Friend','Family')));
CREATE TABLE IF NOT EXISTS ai_companions(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users ON DELETE CASCADE,name TEXT NOT NULL,personality TEXT DEFAULT '',instructions TEXT DEFAULT '',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_conversations(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users ON DELETE CASCADE,assistant_key TEXT NOT NULL,title TEXT DEFAULT 'Conversation',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_messages(id BIGSERIAL PRIMARY KEY,conversation_id BIGINT REFERENCES ai_conversations ON DELETE CASCADE,role TEXT CHECK(role IN ('user','model')),body TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS posts_created_idx ON posts(created_at DESC);
CREATE INDEX IF NOT EXISTS wallet_user_idx ON wallet_transactions(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS ai_messages_conv_idx ON ai_messages(conversation_id,id);
